// Bazaar Worldmaker: what Nemessiah says in her lessons. One entry per line of hers, so a line can be reworded without touching code.
// pose: smile explain think ask smirk guilty shush surprise panic mad. mode: the editor's mode the line is spoken in.
// tab: the economy tab. spot: what on the page she points at. task: something to try (see tutor.js). act: a button she offers.
// names: the words on buttons, tabs and headings that the line speaks of and that must be in sight while she speaks, kept beside
// it so a test can tell when the page and the lesson have drifted apart. far: words on another screen, or on a button that shows later. textBk, poseBk: what she says instead where the page keeps a second copy of the library.
(function () {
  const MME = window.MME = window.MME || {};
  MME.TUTOR = {
    name: "Nemessiah", title: "The Vermilion Prophet",
    card: "I will sit beside you and walk you through the tools one at a time on a practice map: painting land, farms, railways, markets and pilgrims, all the way to a state's government, taxes, money, religion and army",
    chapters: [
      { id: 'welcome', nav: "Welcome", title: "Welcome to the map-making table", mode: 'view', steps: [
        { id: 'welcome-01', pose: 'smile', text: "Here at last, my child? Come closer to the table. My name is Nemessiah. Today I will sit beside you and tell you what each pen on this table is for" },
        { id: 'welcome-02', pose: 'explain', text: "Here you can build a whole map of hexagons: land, mountains, rivers, cities and roads, right up to the borders of states. Then the system works out for you which city makes what, which lacks what, and who it sells to" },
        { id: 'welcome-03', names: ["Save this practice map to the library", "This map"], pose: 'think', spot: '#setcard', text: "The map before you is a practice map. I rolled it up at random for you to try your hand on. Paint over it, erase it, break it if you like. It is not kept in your library unless you press keep this practice map in the this-map card" },
        { id: 'welcome-04', names: ["Contents"], pose: 'smirk', spot: '#tuToc', text: "There are twenty-seven lessons. Hear them in order, or jump to the one you want from the contents button. Now and then I will invite you to try something. You may go on without doing it, but a hand that has done the thing remembers longer than an ear that only listened" },
        { id: 'welcome-05', names: ["Minimise", "Next lesson"], pose: 'ask', spot: '#tuMin', text: "If my speech box covers the map, minimise it. When you are ready, press next lesson or press Enter" }
      ] },
      { id: 'look', nav: "Looking at the map", title: "Look it all over before you begin", mode: 'view', steps: [
        { id: 'look-01', pose: 'explain', text: "The whole map is divided into hexagons. Point the mouse at any hex and the description card on the map tells you its terrain. Point at a city and you get its name and story. The card can be dragged, and folded away with the arrow at its corner" },
        { id: 'look-02', pose: 'ask', spot: '#zin, #zout, #zfit', task: 'view', text: "Turn the mouse wheel to zoom. Press the arrow keys or W A S D to move, or drag the map with the mouse. The zoom and fit-to-screen buttons sit in the map's corner. Try moving it once" },
        { id: 'look-03', pose: 'think', spot: '#scalebar, #setKm', text: "The scale bar sits at the map's edge, where I have circled it for you. How many kilometres one hex spans is set in the this-map card. It reaches all the way into trade, because merchants' carriage is reckoned by real distance: the longer the hex, the dearer the goods by the time they arrive" },
        { id: 'look-04', pose: 'explain', spot: '#modes', text: "The bar along the top holds the work modes, left to right in the order mapmakers usually work: paint the land, draw rivers, place communities, name places, lay roads, then look at trade, climate, the economy and place details. The small number on each button is its shortcut; press one to zero on the keyboard to switch modes at once" },
        { id: 'look-05', pose: 'smile', spot: '#history, #status', text: "If you slip, press undo; the button sits beside the mode bar. Every change you make is saved for you each time. There is no save button for you to remember" }
      ] },
      { id: 'tools', nav: "Tools on the map", title: "Things on the table you can pick up any time", mode: 'view', steps: [
        { id: 'tools-01', pose: 'explain', text: "Rest the mouse still on a community, a special feature or a special zone for about two seconds. A small ring beside the mouse slowly fills, and when it closes a short summary box appears with the kind, state, population and a brief story of that spot. Move the mouse away and the box goes by itself" },
        { id: 'tools-02', names: ["Measure", "Plan a journey"], pose: 'explain', spot: '#rulerBtn, #tripBtn', text: "The measure and travel-plan buttons sit on the map bar. Measure lets you click point after point and tells you the distance in kilometres. Travel plan lets you pin a party, choose how it travels (on foot, on horseback, as an army, by rail, by boat, or on foot then onto a passenger boat at a community's landing), enter a number of days, and the map rings where the party can reach in those days" },
        { id: 'tools-03', pose: 'shush', text: "These two tools are there to help you think. Not a single hex of the map's data moves. The party pin is remembered on your own device only. A game master who wants to know whether the players reach the pass before the snow will love them" },
        { id: 'tools-04', pose: 'ask', text: "Right-click anywhere on the map and a wheel of commands opens around the mouse. On a community it has shortcuts to the community's card, history, trade and market. On an empty hex it has zoom in, hex notes and place a community. While you paint land, the right button still drags the map as before, so the wheel will not pop up under your hand" },
        { id: 'tools-05', pose: 'explain', text: "The bottom right corner of the map holds the minimap. The frame inside it is the part you are looking at. Click anywhere on the minimap and the view moves there. Press H to hide it or bring it back" },
        { id: 'tools-06', names: ["Name the world", "Sound", "Music"], pose: 'smile', spot: '.mapopt', text: "The top right corner has the name-the-world button, where you can set your world's name, current year and era. Next come the sound and music switches. The question-mark button lists every shortcut: M opens the market, R measures, T plans travel, Q changes season, L changes the map's colour layer" },
        { id: 'tools-07', pose: 'think', text: "Cards in the side panel have a small ⧉ button at their head. Press it and the card floats out as a window you can drag anywhere. Community names in cards and windows can be clicked too: the view moves to that community and opens its card at once" }
      ] },
      { id: 'terrain', nav: "Painting land", title: "Land begins at the tip of the brush", mode: 'terrain', steps: [
        { id: 'terrain-01', pose: 'explain', spot: '#pal', text: "This is terrain-painting mode. Choose a kind of ground from this tray (grassland, forest, desert, snow, mountains or sea) and drag on the map" },
        { id: 'terrain-02', pose: 'explain', spot: '#bsize', text: "The brush comes in four sizes: one hex, seven, nineteen and thirty-seven. Coastline work takes a small brush; filling in a continent takes a big one" },
        { id: 'terrain-03', pose: 'ask', task: 'undo', text: "Try a patch. Paint into the sea to extend the land, or turn forest into grassland. To move the map while painting, drag with the right mouse button, or hold space and drag" },
        { id: 'terrain-04', pose: 'think', text: "Starting from empty sea, you can paint the whole land yourself like this. If you would rather not start from nothing, choose random terrain when you make a new map: the system lays out continents, mountains and rivers first and you edit from there. If you already have a continent's shape in mind, choose from an image and send in your drawing; the system reads it as bare land and water" },
        { id: 'terrain-05', names: ["Place mountain ranges automatically"], pose: 'explain', spot: '#autoMt, #autoMtAmt', text: "Land you paint yourself has no mountains yet. The place-ranges-automatically button lays them in long lines that follow the shape of the land, set back from the coast, with passes left open for people to cross. You can choose from three amounts" },
        { id: 'terrain-06', pose: 'smirk', text: "If you dislike the mountains the system laid, you can always paint over them. The system proposes; you decide" }
      ] },
      { id: 'river', nav: "Rivers", title: "Water always flows downhill", mode: 'river', steps: [
        { id: 'river-01', names: ["Place rivers automatically"], pose: 'explain', spot: '#autoRiv, #autoRivAmt', text: "Rivers have their law: water starts high and always flows downhill. The place-rivers-automatically button knows this law. Sources start in the mountains, tributaries join the main stream, and each ends at the sea or a lake" },
        { id: 'river-02', pose: 'ask', spot: '#autoRiv', task: 'rivers', text: "Press it and notice that the wet side gets great rivers while dry land gets only seasonal streams" },
        { id: 'river-03', names: ["Draw line", "Finish line", "Erase rivers"], pose: 'explain', spot: '#rtool, #rfinish', text: "To draw one yourself, choose draw line, click along the way the water should run, then press end line. To erase, choose erase river and click the streams you don't want" },
        { id: 'river-04', pose: 'think', text: "Rivers change the trade of a whole basin. Goods that go by boat travel cheaper than goods on a cart, so riverside cities trade further, and some goods arise only in hexes beside a river" },
        { id: 'river-05', pose: 'smirk', spot: '#rkind button[data-k="canal"]', text: "The row of line kinds also holds dug canals. A canal does not follow the low ground; it goes where hands dig it, so the line runs straight through the points you click. It has stone banks and locks, and seagoing ships can sail through. Cut across an isthmus to join two seas, as at Panama, and watch the trade routes of the whole continent change with it" }
      ] },
      { id: 'feat', nav: "Special features", title: "One oasis changes the caravan road", mode: 'terrain', steps: [
        { id: 'feat-01', names: ["Special features"], pose: 'explain', spot: '#featPal', text: "Below the terrain palette is a row of special features: oasis, mangrove, hot spring, steep canyon, waterfall, sinkhole and many more. Paint them over hexes with the same brush. Each kind goes only on ground that suits it, so a reef cannot grow on land" },
        { id: 'feat-02', pose: 'think', text: "Special features have four real effects: the hex yields more; some kinds let farms stand even in the middle of a desert; watering stops make crossing dry land cheaper for caravans; and some places draw tourists and lift the well-being of the cities around them" },
        { id: 'feat-03', names: ["Place special features automatically"], pose: 'smirk', spot: '#featAuto', text: "Too lazy to paint one hex at a time? Press place special features automatically and I will read the land for you: where an oasis belongs, where a river meets the sea in a delta. If you don't like it, one undo and it is all gone" },
        { id: 'feat-04', names: ["Special features"], pose: 'explain', spot: '#featcard h2', text: "The special-features card in the side panel lets you change the numbers of every kind, and make new kinds of your own world too: a mana spring or a giant mushroom grove, why not? Give it the output you want and paint it onto the map" },
        { id: 'feat-05', pose: 'think', text: "Some kinds look like ordinary terrain (mangrove, volcanic soil, peat bog or sinkhole) and fill the hex with their own colour. Oasis and hot spring show as a pale tint with a mark. To switch a kind between the two looks, pick from the appearance box in that kind's card" },
        { id: 'feat-06', pose: 'explain', text: "Standing stones, ancient ruins and the old points of interest now live with the special features. An old map that still has these points shows a button in the points-of-interest card to move them all into special features. One press, and their names, notes and holiness all come along" }
      ] },
      { id: 'city', nav: "Communities and roads", title: "Wherever people live, the road reaches", mode: 'city', steps: [
        { id: 'city-01', names: ["Capital", "Fortress", "Hamlet", "Monastery", "Tribal camp", "Way station"], pose: 'explain', mode: 'city', spot: '#ckind', text: "Community mode: choose a kind first (capital, city, town, fortress, village, hamlet, monastery, tribal camp or waystation), then click an empty spot on the map, type a name and press Enter. A monastery has few people but is holy; a tribal camp herds far afield; a waystation is always a stop on the trade lines" },
        { id: 'city-02', pose: 'ask', mode: 'city', task: 'cities', text: "Place a city. Choose a site where you think people would want to live: a river mouth, a sheltered bay, or a mountain pass where everyone who goes through must pay" },
        { id: 'city-03', pose: 'explain', mode: 'city', spot: '#opts', text: "Click an existing community to edit its name, kind, notes and population. Leave population blank and the system uses the value for its kind and traits; fill it in and the community produces, consumes and bargains for the number of people you entered" },
        { id: 'city-03b', pose: 'think', mode: 'city', spot: '#opts', text: "The same card has traits to tick: major port, walled, religious centre, or slums. Each one changes people, well-being and what the community makes. There is a box for the community's tax rate, the culture and religion it holds, and a button to write the community's history at length" },
        { id: 'city-04', pose: 'explain', mode: 'label', text: "Place-name mode is for naming seas, ranges, forests or realms. You can adjust size, angle and colour. Once placed, drag to move" },
        { id: 'city-05', names: ["Connect cities that have no road"], pose: 'explain', mode: 'route', spot: '#rtLoose', text: "Road mode: click the starting city, then the destination, and the road finds the shortest way by itself, skirting mountains and big rivers, with tunnels or bridges where it can't. The connect-unroaded-cities button gathers up any cities left out" },
        { id: 'city-06', pose: 'smirk', mode: 'route', text: "If you dislike a road, drag it to bend its course. Its ends can move to other cities too. Real roads never ran where the planners meant them to either" }
      ] },
      { id: 'farm', nav: "Farms and specialities", title: "Each village has its own knack", mode: 'city', steps: [
        { id: 'farm-01', pose: 'ask', act: 'town', text: "Press the button below and I will open a sample city's card. Each community can choose one speciality: mining village, salt pans, fishing village, horse stud, on to craft villages that distil spirits, fire bricks or weave cloth. Its speciality doubles, and other things it gathers fall a little" },
        { id: 'farm-02', pose: 'think', text: "Once a speciality is chosen, the community's harvest area leans toward its own source. A mining village walks further toward the mountains; a fishing village sails deeper than the rest. You can see it in the gold outline on the map; the blue water hexes inside it are the fishing grounds" },
        { id: 'farm-03', names: ["Farmland and livestock"], pose: 'explain', spot: '#cfFarm input[data-fm="g"], #cfFarm input[data-fm="p"], #cfFarm input[data-fm="c"]', text: "Below the speciality is the farmland. You can split how much goes to grain fields, pasture and cash crops. More pasture gives more meat, milk, hides and working animals but less grain. Cash crops are tea, cotton, silk, grapes: things that fetch a price" },
        { id: 'farm-04', pose: 'explain', spot: '#cfFarm select[data-fm="m"], #cfFarm select[data-fm="h"]', text: "Then choose how to farm: two fields with fallow, three-field rotation, manure from the herds, bought fertiliser, or irrigation. Animals can graze open land, be stall-fed, or be driven as nomads. Tick use draught animals too for more grain" },
        { id: 'farm-05', pose: 'shush', text: "Fertiliser, fodder and working animals must really be bought. The system works the year out twice: the first pass sees how much can be bought, the second gives the effect from that. A village that orders fertiliser when nobody makes any gets only the carriage bill. Try setting up a fertiliser village nearby" }
      ] },
      { id: 'rail', nav: "Railway", title: "Iron rails shrink the land", mode: 'route', steps: [
        { id: 'rail-01', names: ["Railway"], pose: 'explain', spot: '#rtCls', text: "Road mode has railways besides royal roads, dirt roads and cart tracks. Choose it and click the starting and destination cities; the rails find the flattest way by themselves. Trains cannot climb steep grades, so they tunnel under mountains and bridge big rivers more often than roads do" },
        { id: 'rail-02', names: ["Connect cities that have no road"], pose: 'shush', spot: '#rtLoose', text: "The connect-unroaded-cities button lays only roads, never rails. Railways exist only where you mean to build them. A world with trains and a world still on carts belong to different ages, and you are the one who chooses" },
        { id: 'rail-03', pose: 'think', text: "On rails, goods and people both travel at about half the cost of a royal road, so two cities joined by rail trade more and visit each other more often. Lay a line, then go look at trade mode: the trade line there grows thicker" },
        { id: 'rail-04', names: ["Routes"], pose: 'explain', spot: '#layersBtn', text: "The routes button on the map bar opens the list of line layers, where you can hide or show railways, each kind of road, and travellers' lines. A saved image follows what you have turned on" }
      ] },
      { id: 'trade', nav: "Trade", title: "Goods flow from plenty to want", mode: 'trade', steps: [
        { id: 'trade-01', pose: 'explain', text: "Trade mode: the lines you see are merchants' ways, worked out by the system from what you have placed. Each city makes goods from the terrain around it and consumes by its number of people; the surplus is carried to cities that lack it" },
        { id: 'trade-02', names: ["Select", "Trade"], pose: 'ask', spot: '#tdTool, #tradecard', text: "With the select tool, click a city to see what it makes, what it lacks and whom it trades with. Click a line to see what it carries. Details appear in the trade card on the right" },
        { id: 'trade-03', pose: 'think', spot: '#tdCat', text: "The goods-category box filters one category at a time. Choose grain and watch where this continent's food flows from and to. Thick lines carry the most" },
        { id: 'trade-04', pose: 'explain', text: "Prices move with scarcity. A city short of something will pay dear; a city with a glut must sell cheap. Merchants carry goods when the price gap covers the carriage. The longer the road, the harder it is, and the more valuable the goods must be to be worth it" },
        { id: 'trade-05', pose: 'shush', text: "Routes carry danger too. Click a line and look in the trade card. The system rates it from how far the way runs from cities, through lands no state controls, and over hard terrain. Dangerous lines cost more to carry along. If you know bandits swarm in that stretch, you can set the level yourself" },
        { id: 'trade-06', names: ["Lay a trade line", "Restore the automatic network"], pose: 'explain', spot: '#tdTool, #tdReset', text: "Lines the system didn't draw you can draw yourself with the trade-line tool. If your edits get tangled, the restore-automatic-network button takes you back to what the system worked out" }
      ] },
      { id: 'market', nav: "Central goods market", title: "Prices rise and fall with the seasons", mode: 'trade', steps: [
        { id: 'market-01', names: ["Market"], pose: 'explain', spot: '#mkBtn', text: "The market button on the map bar, or M, opens the central goods market. The system divides the land into regions around the large communities that are trade hubs. Each region has its own market showing supply, demand, stock in the warehouses and the price of every kind of goods" },
        { id: 'market-02', pose: 'think', text: "The market moves with the seasons. After harvest, grain overflows the warehouses and the price falls; by the end of winter the stores run low and the price climbs. Choose a season in the market window to see one stretch at a time. Click a good to see its price line for the year and the list of communities selling it; a community's name there takes you straight to it" },
        { id: 'market-03', pose: 'explain', text: "There are two kinds of price. The price per portion is reckoned from what one person uses in a year. The price per piece is what a character in the game actually pays at the market stall: a kilogram of rice, a log of timber, a bolt of cloth. How many pieces make a portion can be changed in each good's details" }
      ] },
      { id: 'travel', nav: "People travel", title: "People travel the same lines as goods", mode: 'trade', steps: [
        { id: 'travel-01', pose: 'explain', text: "Four kinds of people travel the trade lines: tourists, people visiting kin or on errands, pilgrims, and business people following the goods. The pale purple dashed lines laid over the trade lines are these people; the thicker, the more of them" },
        { id: 'travel-02', pose: 'think', text: "Each kind travels differently. Most personal travel stays within the state and goes no great distance. Pilgrims will walk far to reach a holy place. Business people come and go with the value two cities trade. Everyone takes the cheapest way, so good roads and railways draw people just as they draw caravans" },
        { id: 'travel-03', pose: 'ask', text: "Click a city on the map. Its card has a section on people's travel, telling who visits, who leaves, and how much visitors spend in the city. There you can make a city holy at three levels, from a local shrine up to a great pilgrimage centre" },
        { id: 'travel-04', pose: 'smile', text: "Cities that reach a holy place easily live better; faith is one of people's needs. The holy city earns from its pilgrims. Lay a railway to a great temple and watch the well-being of the cities along the line go up" },
        { id: 'travel-05', pose: 'explain', text: "If you don't set it yourself, a city can grow holy from a religious organization's house, from being the centre of a religion, from a monastery in the city, from special features like standing stones or ancient ruins nearby, or from a sacred peak in view. A map with no holy place at all has not a single pilgrim" }
      ] },
      { id: 'climate', nav: "Climate", title: "The land's weather", mode: 'climate', steps: [
        { id: 'climate-01', names: ["Summer weather", "Winter weather", "Moisture", "Dryness", "Elevation"], pose: 'explain', spot: '#clLayer', text: "Climate mode has five layers to view: summer weather, winter weather, moisture, dryness and elevation. The system reads them from what you painted: thick forest means much rain, desert means little, mountains mean high and cold" },
        { id: 'climate-02', names: ["Raise", "Lower"], pose: 'explain', spot: '#clTool, #clBrush', text: "To edit hex by hex, choose the layer to edit, choose raise or lower, choose a brush size and drag on the map. Before you press, the hexes the brush will touch light up under the mouse. Lift ground into a plateau, add rain to a valley, or make a strait colder than its surroundings" },
        { id: 'climate-03', names: ["Elevation", "Raise", "Summer weather"], pose: 'ask', spot: '#clLayer, #clTool', task: 'clim', text: "Choose the elevation layer, press raise, and drag over the land once. Then switch to the summer weather layer: the ground you raised has cooled by itself, because all the values are tied together" },
        { id: 'climate-04', pose: 'think', spot: '#clSetRow', text: "This row governs the whole map. The latitude of the top and bottom edges tells whether the land lies near a pole or near the equator. The nearer the pole, the colder, and the further apart winter and summer. The prevailing wind tells which side the rain comes from: the side facing the sea wind is wet, the lee of the ranges dry. For a map of the southern hemisphere, enter negative latitudes" },
        { id: 'climate-05', names: ["Seasons of the year", "Add a season"], pose: 'explain', spot: '#clseasbox', text: "A map's year is divided into seasons; see the seasons-of-the-year section in the climate card. It starts with four. For three, as in the tropics, delete one; for a monsoon, press add season. Each season sets its own length, heat, rain and wind direction" },
        { id: 'climate-06', names: ["Part of the year", "Show on the map"], pose: 'explain', spot: '#clSeason, #clLayer', text: "Choose a season from the time-of-year row, or press view on the map in that season's card. The data layer changes to that single season's weather and rain, and the brush edits only the season you are viewing. A field dry only in summer, or a pass snowed shut only in winter, is made from here" },
        { id: 'climate-07', pose: 'smile', text: "Climate reaches back into goods too. Crops grow only in seasons warm enough and wet enough, so places cold most of the year harvest little, and cities with long winters need a lot of fuel. Edit the weather and trade is worked out again by itself" }
      ] },
      { id: 'goods', nav: "Goods and prices", title: "What this land gives", mode: 'econ', tab: 'goods', steps: [
        { id: 'goods-01', names: ["Goods"], pose: 'explain', tab: 'goods', spot: '#ecoTab', text: "Economy mode has ten tabs. Start with the goods tab: the list of everything this land can give. A new map takes real-world goods as its base: wheat, fish, salt, timber, iron, on to spices and gems" },
        { id: 'goods-02', pose: 'ask', tab: 'goods', spot: '#ecocard', task: 'eco', text: "Click a good in the economy card. You can rename it, move its category and adjust its abundance. A hundred percent is normal; halve it and output halves; set it to zero and this land has none of that good. Try adjusting one" },
        { id: 'goods-03', names: ["Add new goods"], pose: 'think', tab: 'goods', text: "Each good has conditions for where it arises, and you can write your own: say, in deciduous forest, only in hexes beside a river, and no more than two hexes from mountains. The add-condition button is in the good's card; the add-new-good button sits at the top of the list" },
        { id: 'goods-04', names: ["Classes and prices"], pose: 'explain', tab: 'cats', spot: '#ecobody .etr[data-c="rare"], #ecobody .etr[data-c="mana"]', text: "The categories and prices tab: a category is a price level, and goods in the same category share a base price, so gems and crude oil are about equally dear while grain and fish are cheap. But a city short of food will pay up to 1.75 times the base price" },
        { id: 'goods-05', names: ["Add category"], pose: 'explain', tab: 'cats', spot: '#ecobody [data-a="unew"]', text: "Bulk is the carriage cost. Heavy cheap goods like stone don't travel far; light dear goods like spices cross continents. For a category of your own, such as mana crystals or silk, press add category in this tab and move goods into it" },
        { id: 'goods-06', names: ["Factory recipes"], pose: 'think', tab: 'cats', spot: '#ecoWorkHead, #ecobody [data-w="tools"]', text: "At the end of the same tab are the workshop recipes: how much ore and fuel one unit of tools uses. You can edit them, and add raw materials from categories you made yourself. A city's workshops short of raw materials produce in proportion to what they can get" },
        { id: 'goods-07', names: ["Add factory goods and a new recipe"], pose: 'explain', tab: 'cats', spot: '#ecobody [data-a="unewm"]', text: "Want glass, gunpowder or gold-threaded silk that this continent doesn't have yet? Press add workshop good and new recipe, then write the recipe yourself: what raw materials one unit uses, and how much. If people suffer without it, tick count as a basic good too" },
        { id: 'goods-07b', pose: 'explain', tab: 'cats', text: "Workshops now make more than tools and weapons: spirits, furniture, brick and lime, fertiliser, fodder, cloth, pottery, processed food, medicine and jewellery. Horses, cattle, buffalo and mules are goods too, used to plough, haul carts and serve as warhorses" },
        { id: 'goods-07c', pose: 'think', tab: 'cats', text: "A city that makes far more of a category than its people use gains from it. Plenty of bricks, sturdy houses; plenty of medicine, little sickness; plenty of jewellery, and the wealthy come by on their own. See it in the city's card in trade mode" },
        { id: 'goods-08', pose: 'smirk', tab: 'cats', text: "Play with the thought: if salt were scarce across the whole continent, which city would grow rich, and who would want to seize it? A good map tells its own stories from questions like that" }
      ] },
      { id: 'states', nav: "States and governments", title: "Lines people draw across the land", mode: 'econ', tab: 'states', steps: [
        { id: 'states-01', names: ["States and borders", "Add state"], pose: 'explain', tab: 'states', spot: '#ecocard', text: "The states and borders tab: press add state, give it a name, choose a colour, then paint the state's area onto the map. Painting into the sea works too; that part counts as the state's waters" },
        { id: 'states-02', pose: 'ask', tab: 'states', task: 'states', act: 'states', text: "You can try making one yourself, or press the button below and I will place three sample states for you to look at first" },
        { id: 'states-03', pose: 'explain', tab: 'states', text: "Cities in the same state share goods first, and only sell the rest outside the state. Border villages next to an ally can trade across the line right away without waiting" },
        { id: 'states-04', pose: 'shush', tab: 'states', text: "Relations are set one pair at a time: ally, neutral or rival. Rivals don't trade, and trade lines skirt a rival's lands and waters when there is another way. Where there is no way round, the route grows dearer by the stretch that must pass through" },
        { id: 'states-05', pose: 'explain', tab: 'states', text: "Each state can choose one of five economic systems. Traditional trades only close to home. Feudal sends goods through the centre a community answers to. Mercantilist shuts out foreign workshop goods and hoards raw materials. Capitalist trades freely; the state's markets warehouse passing goods and act as middlemen between rivals. Socialist gathers goods at the central city and hands them out by need" },
        { id: 'states-06', pose: 'surprise', tab: 'states', text: "Change the system of a single state, then go back to trade mode, and you will see the whole continent shift with it. When one state closes its doors, another must find its goods further away than before" },
        { id: 'states-07', pose: 'explain', tab: 'states', text: "A state that buys more than it sells, until its deficit runs deep, leaves its people worse off. Each state can choose its remedies: import duties, export subsidies, devaluation, import substitution, austerity or promoting tourism. Tick them in the state's card and the state acts by itself when it runs a deficit" },
        { id: 'states-08', pose: 'smirk', tab: 'states', text: "One system has no ruler at all. Anarchic lands trade like a black market: they sell to anyone, count no one a rival and have no tariff walls. They suit a pirate island or a wild land between kingdoms" },
        { id: 'states-09', pose: 'shush', tab: 'states', text: "Another thing the real world once had: each state may choose to abolish slavery, use a patronage system, or trade slaves freely. Slaves come from poverty and low well-being; cities so crowded that labour is cheap have fewer slaves by themselves. You may write a cruel world or a kind one; the system only shows you the results" }
      ] },
      { id: 'gov', nav: "Government", title: "Who holds the sword, who holds the purse", mode: 'econ', tab: 'states', steps: [
        { id: 'gov-01', names: ["Government"], pose: 'explain', tab: 'states', spot: '#ecobody details[data-fold="stA"] select[data-gv]', text: "In the state's card, under government and law, is the government box. You can choose from twenty kinds: absolute monarchy, feudal kingdom, mandala, empire, republic, city-state, federation, confederation, tribal council, khanate, theocracy, on to company states and commune federations" },
        { id: 'gov-02', pose: 'think', tab: 'states', text: "A government says where power gathers. An absolute monarchy takes nearly all taxes into the palace and the provincial towns can hardly levy their own. A confederation is the reverse: the cantons collect almost everything and the centre has hardly any money. The government also names the administrative units: a republic gets districts, provinces and regions; a khanate gets yurts, tumens and uluses" },
        { id: 'gov-03', pose: 'explain', tab: 'states', spot: '#ecobody details[data-fold="stA"] .polset.gtr', text: "Below the government are state traits to tick. The upper set belongs to the chosen government and changes when the government changes. The lower set works for any state: strong bureaucracy, secret police, free port, royal granaries. Point at a name to see what it does" },
        { id: 'gov-04', pose: 'smirk', tab: 'states', text: "Every one has a price. Secret police keep the realm quiet but the people unhappy, and martial law even more so. Choose to suit the story you will tell. A perfect state tells the dullest story of all" }
      ] },
      { id: 'adm', nav: "Government", title: "From county to throne", mode: 'econ', tab: 'adm', steps: [
        { id: 'adm-01', names: ["Government"], pose: 'explain', tab: 'adm', spot: '#ecoTab', act: 'states', text: "The government tab divides a state the Crusader Kings way. The smallest tier is the county, one stretch of land; the communities in a county are its baronies. Several counties make a duchy, several duchies a kingdom. Duchies and kingdoms are de jure lands: whichever state holds half their counties holds that title. If the practice map has no states yet, press the button below and I will place them first" },
        { id: 'adm-02', names: ["Divide units automatically"], pose: 'ask', tab: 'adm', spot: '#ecobody details[data-afold="A"] [data-aa="build"]', text: "Under each state's name is a divide-units-automatically button. The system divides by communities and paths. A duchy on a rival's border becomes a march, a military district that makes many weapons, though its people live harder. Press it for one state and look at the three sizes of line that appear on the map" },
        { id: 'adm-03', names: ["County", "Duchy", "Kingdom"], pose: 'explain', tab: 'adm', spot: '#admLv', text: "The click-to-choose-level row says which tier of unit a click on the map gives you. Click inside a state's area and the unit's card comes up to rename it, move it under another unit, or dissolve it. Hold Shift and click a neighbouring county to annex it into the selected unit. The new county, duchy or kingdom buttons create an empty unit; then Shift-drag or click on the map to give it land. A county can also be marked full incorporation, not incorporated, or colony, as in Victoria" },
        { id: 'adm-03b', pose: 'ask', tab: 'adm', act: 'unit', spot: '#keyhint', text: "Press the button below and I will divide the first state and choose its smallest district for you. Look at the bar along the bottom edge of the map: it tells what the tool in your hand can do. Hold Shift and the district to be annexed shows a blue outline under the mouse before you click" },
        { id: 'adm-03c', pose: 'explain', tab: 'adm', spot: '#ecobody input[data-uf="rate"], #ecobody input[data-uf="toll"]', text: "A district's card has its own economy: people, GDP, trade across its borders, local taxes, budget and treasury. A district sets its own tax rates and budget, and can set tolls on goods entering. Make the tolls too high and little comes in from outside, so people in the district rely on what is made inside. Allies and rivals remain the law of the state" },
        { id: 'adm-04', names: ["Merge states", "Keep this state as a principality"], pose: 'smirk', tab: 'adm', spot: '#ecobody details[data-afold="A"] [data-aa="join"]', text: "Two states can merge. Choose whom this state will merge into, then press merge states. Tick keep this state as a principality and the old state lives on as a self-governing unit under the new throne. Its people fare better than a realm swallowed whole" },
        { id: 'adm-05', names: ["Old Thai names"], pose: 'explain', tab: 'adm', spot: '#ecobody [data-aa="namesTh"]', text: "The names of each tier come from the government chosen in the state's card. A republic gets districts, provinces and regions; a tribal council gets ranges, tribes and tribal unions. States with no government chosen use the names at the end of this tab. For a Siamese flavour, press the old Thai names, or choose the mandala government outright" }
      ] },
      { id: 'fisc', nav: "Finance and taxes", title: "Two purses", mode: 'econ', tab: 'states', steps: [
        { id: 'fisc-01', names: ["States and borders"], pose: 'explain', tab: 'states', spot: '#ecobody details[data-fold="stA"] h5[data-sec="fisc"]', text: "Back to the states and borders tab. Each state's card has a section on finance, customs and embargoes. A state can tax six ways: poll tax, land tax, corporate tax, value-added tax, market licences and import duty. The figure beside each box tells how much each brings in a year" },
        { id: 'fisc-02', pose: 'think', tab: 'states', text: "Taxes go into two purses. The first is the centre's: the state collects directly from every community into the royal treasury. The second is local: each tier of government collects from the people in its own area at that tier's rate and spends it there. A principality sends only half to the centre. Corruption leaks from both purses. Each tier's rate can be edited in the same section, or set for a single unit in the government tab" },
        { id: 'fisc-03', pose: 'explain', tab: 'states', text: "The treasury is split four ways: defence, administration and court, public works and utilities, and welfare. Public works make carriage on the state's roads cheaper; welfare lifts well-being; defence is the budget that feeds the army" },
        { id: 'fisc-04', pose: 'shush', tab: 'states', text: "Every community has its own stability. The tax burden, missing necessities, a culture or religion different from most of the state, and war nearby drag it down; welfare and defence spending pull it up. Open a community's card to see how much each one takes away" },
        { id: 'fisc-05', names: ["Add rule"], pose: 'mad', tab: 'states', spot: '#ecobody details[data-fold="stA"] [data-rf="new"]', text: "For trade abroad, press add rule, then choose a partner state and a goods category. Set a customs duty for that pair alone, or embargo it outright. Embargoed goods may be neither bought nor sold, and merchants must find them elsewhere" }
      ] },
      { id: 'money', nav: "Money", title: "Whoever prints the money holds the power", mode: 'econ', tab: 'states', steps: [
        { id: 'money-01', names: ["Money used"], pose: 'explain', tab: 'states', spot: '#ecobody details[data-fold="stA"] select[data-cn="use"]', text: "Under name, colour and money, the money-used box gives three choices: use the world's common money, issue the state's own, or use money another state issues, as many countries use the dollar or many states share the euro" },
        { id: 'money-02', pose: 'think', tab: 'states', text: "A state that issues its own money chooses what it is made of. Full-weight gold coin is the steadiest, but gold must be bought to strike it. Alloy coin makes the state a profit, but people don't quite trust it. Gold-convertible notes are fairly steady. Floating notes swing hard with the trade balance but earn the state the most" },
        { id: 'money-03', pose: 'smirk', tab: 'states', text: "Whoever uses your money pays a minting fee into your treasury every year, and their currency rises and falls with yours. Trade between you needs no exchange. So money is another kind of power, one that never needs to march an army anywhere" },
        { id: 'money-04', pose: 'explain', tab: 'gdp', text: "The GDP and currency tab has the world's currency table, showing who issues each currency, what it is made of and which states use it. The common money is given as a price in rice: how many days one coin feeds a person, so you can feel whether a sum is large or small" }
      ] },
      { id: 'belief', nav: "Culture and religion", title: "Strangers and other faiths", mode: 'econ', tab: 'cul', steps: [
        { id: 'belief-01', names: ["Culture", "Add culture", "Create one culture per state", "Spread from large communities"], pose: 'explain', tab: 'cul', spot: '#ecobody [data-bl="new"]', text: "The culture tab: press add culture, give it a name, choose a colour, then paint it onto the map just like a state's area. Too lazy to paint? There are two shortcuts: create one culture per state, or spread from large communities, letting each culture creep outward along the paths people walk" },
        { id: 'belief-02', pose: 'think', tab: 'cul', text: "Each culture can tick traits: mercantile, warrior, scholarly, artisan, seafaring, insular, and many more. Each changes what people make, what they want and how well they live. Two communities of different cultures can trade, but carriage costs a little more: they don't quite understand each other, and trust is thin" },
        { id: 'belief-02b', pose: 'ask', tab: 'cul', spot: '#belBrush', text: "While you hold the culture brush, the aiming ring on the map shows which hexes it will paint. The brush has four sizes like the land brush. The bar at the bottom edge of the map tells you how to erase too: hold right-click and drag" },
        { id: 'belief-03', names: ["Religion", "Add religion"], pose: 'explain', tab: 'rel', spot: '#ecobody [data-bl="new"]', text: "The religion tab works the same way, with three things culture lacks. The faithful pay a share of their income as an offering to the religion's centre. Pilgrims travel mainly to the holy places of their own religion. And religious organizations can be tied to a religion" },
        { id: 'belief-04', pose: 'smile', tab: 'rel', text: "A community takes the culture and religion of the ground it stands on. To make a city differ from its neighbours, set it in the community's card. A city of priests in a heretic land is possible; just be ready for its stability to be poor" },
        { id: 'belief-05', names: ["Layer"], pose: 'smirk', tab: 'rel', spot: '#belBtn', text: "The layer button on the map bar switches the map's colouring: off, culture, religion and government. L does it too. Look and you will see that the lines of faith and the lines of borders rarely lie exactly on top of each other. Where they slip apart is where stories tend to happen" }
      ] },
      { id: 'army', nav: "Army", title: "Every regiment needs someone to pay for it", mode: 'econ', tab: 'army', steps: [
        { id: 'army-01', names: ["Army"], pose: 'explain', tab: 'army', spot: '#ecoTab', text: "The army tab holds the unit types of the whole world: infantry, archers, cavalry, heavy infantry, gunners, sailors and field mages. Each type says how much weapons, armour, horses, supplies and tools one soldier uses, and what skill it has. Every number can be edited" },
        { id: 'army-02', pose: 'think', tab: 'army', text: "A soldier's gear is real goods: swords and spears, metal armour, warhorses, siege engines, warships, supplies and medicine, each with its stats in the same tab. So a state with many soldiers needs a lot of these things, its smiths do good business, and the arms trade lines grow thicker with it" },
        { id: 'army-03', names: ["Soldiers per population", "Men per regiment"], pose: 'explain', tab: 'states', spot: '#ecobody details[data-fold="stA"] [data-am="mob"]', text: "Each state's soldier numbers are set in the state's card. Soldiers per population says what percentage of people are levied; men per regiment gives the size of a regiment; then you share out how many of each unit type there are. When the defence budget falls short, the state gets only as many soldiers as it can pay" },
        { id: 'army-04', pose: 'shush', tab: 'states', text: "An army can push prices down too. When two states that are not allies trade across a border, the stronger squeezes the weaker on price. If both states have armies, strength is measured by fighting power; if not, by the size of the economy" }
      ] },
      { id: 'orgs', nav: "Organizations", title: "Guilds, temples and societies", mode: 'econ', tab: 'orgs', steps: [
        { id: 'orgs-01', names: ["Add organization"], pose: 'explain', tab: 'orgs', spot: '#ecobody [data-a="onew"]', text: "The organizations tab: press add organization, give it a name, choose a kind (craft guild, society, charity, religious order, or something you invent yourself), then set up its head office first. Only then branch out to other cities. The head office does more work than a branch, and branches send profits back every year" },
        { id: 'orgs-02', pose: 'think', tab: 'orgs', text: "Organizations can work many ways: raise output, raise the value of goods, lift well-being, cut transport costs, or trade across state lines for a fee. Each organization has its own value, shown in the GDP and currency tab" },
        { id: 'orgs-03', pose: 'smile', tab: 'orgs', text: "A religious organization's house makes a city holier too. Wherever you set a branch of a great temple, pilgrims travel to that city" }
      ] },
      { id: 'gdp', nav: "GDP and currency", title: "Who is rich, who is struggling", mode: 'econ', tab: 'gdp', steps: [
        { id: 'gdp-01', names: ["GDP and currency"], pose: 'explain', tab: 'gdp', spot: '#ecocard', text: "The GDP and currency tab shows how much value each state and each city creates in a year, reckoned from what it makes and the prices it actually sells at" },
        { id: 'gdp-02', pose: 'explain', tab: 'gdp', text: "Everything is measured in the common money, or think of it as rice: how many days one coin of common money feeds a person is shown above. Whether a state issues its own money, uses another state's, or simply uses the common money is chosen in the state's card. An issuer earns a minting fee from everyone who uses its money, and states sharing a currency trade without exchanging money" },
        { id: 'gdp-03', pose: 'think', tab: 'gdp', spot: '#ecobody details[data-fold="gct"] .etable.g5 .eth.sortable', text: "The income column is money after the system has had its hand on it. Capitalist cities take a middleman's share, feudal communities send tribute to the centre, socialist states even out income between cities. So income per head tells people's well-being more truly than GDP" },
        { id: 'gdp-04', pose: 'smile', tab: 'gdp', text: "Cities the table shows lacking many kinds of goods are cities in hardship. Ask yourself why: a poor site, encircled by rivals, or more people than the land around can feed. The answer often becomes the plot of a story" },
        { id: 'gdp-05', names: ["Numbers"], pose: 'explain', tab: 'tune', spot: '#ecoTab', text: "The figures tab holds every value the model uses: the middleman's share of capitalist markets, feudal tribute, exchange costs, right down to the number of people that turns a village into a city. The defaults belong to whoever built this tool; your world can use other values, and every one can be edited. The map remembers only the ones you change" }
      ] },
      { id: 'people', nav: "Population and classes", title: "People give the land its worth", mode: 'econ', tab: 'gdp', steps: [
        { id: 'people-01', names: ["Total population of the map"], pose: 'explain', tab: 'gdp', spot: '#tierSel', text: "The bar above the map has a box for the map's total population. Choose one of three levels (low, a few million; medium, a few hundred million; high, a billion) or type a number yourself. This figure sets city sizes, GDP and the land cities need" },
        { id: 'people-02', names: ["City land"], pose: 'think', tab: 'gdp', spot: '#landBtn', text: "A city of many people must eat into the land around it: clearing forest for farms, felling timber, digging into mountains. The city-land button shows this on the map. A city short of land must buy food from elsewhere" },
        { id: 'people-03', names: ["Harvest per hex"], pose: 'explain', tab: 'gdp', spot: '#ecobody details[data-fold="ghv"] > summary', text: "The people working the land decide how much each hex yields. A thinly peopled hex is not fully harvested; a crowded one gives more, up to three times. Forest yields, though, dwindle as people pour in. The harvest-per-hex section gives every city's figures" },
        { id: 'people-04', names: ["Population, migration and tourism"], pose: 'explain', tab: 'gdp', spot: '#ecobody details[data-fold="gpp"] > summary', text: "People leave cities where life is hard for better ones. Each state chooses whether newcomers cluster, spread out or move with the seasons. This section shows which cities lose people, which gain them, and where tourists go" },
        { id: 'people-05', names: ["Classes and wealth"], pose: 'think', tab: 'gdp', spot: '#ecobody details[data-fold="gcl"] > summary', text: "A city's people fall into four classes by where their income comes from: upper, middle, lower and lowest. The classes and wealth section shows who the money gathers around and what that does to the city. People who aren't wealthy care more for necessities from their own state than for costly goods from far lands" },
        { id: 'people-06', pose: 'smile', tab: 'gdp', text: "Workshop labour regimes can be chosen too: home crafts, single-shift workshops, long-shift crash production, or two shifts with welfare. Set them for the whole state in the state's card, or city by city in the city's card. Each has its price. The workshops that make the most are seldom where people live best" }
      ] },
      { id: 'notes', nav: "Special zones and notes", title: "A map that remembers its stories", mode: 'info', steps: [
        { id: 'notes-01', names: ["Choose data", "Paint special zones"], pose: 'explain', spot: '#ifTool', text: "Places and data mode is where the map keeps its stories. With the select-data tool, click any hex: the selected-data card tells which state, administrative unit and zone that hex is in, and from there you can open the notes for each" },
        { id: 'notes-02', names: ["World data"], pose: 'think', spot: '#setWorld', text: "Notes can be formatted with bold, italics, headings and lists. A community has a history button in its card; a state has a write-state-history button. The story of the whole world (its name, current year and era) sits behind the world info button in the this-map card" },
        { id: 'notes-03', names: ["Paint special zones", "Special zones"], pose: 'shush', spot: '#ifTool, #szBtn', text: "A special zone is an area that is dangerous or temporary: war, bandit country, disaster, plague, monsters or unrest. Choose paint special zone, choose its kind, then drag on the map. Drag with the right button to erase. The special-zones button on the map bar hides or shows their pattern" },
        { id: 'notes-04', pose: 'think', text: "Special zones have real effects. Trade lines through a dangerous zone cost more and run more risk. Communities in a zone live harder by as much as you set, and their stability falls. A zone's name, danger level and notes can be edited in its card. When the war ends, erase the zone and trade goes back the way it ran before" }
      ] },
      { id: 'room', nav: "Editing with friends", title: "One table, many hands", mode: 'view', steps: [
        { id: 'room-01', names: ["Open a shared room"], pose: 'explain', spot: '#roomOpen', text: "A big map is lonely work alone. The open-shared-room button sits in the top right corner. Open it and you get a ten-character room code. Send it to friends; they enter the code on the menu page and come in to edit the same map with you" },
        { id: 'room-02', pose: 'think', text: "The map still lives on your device alone. Your friends' devices hold it only while they are in the room. The moment you close the room or this page, everyone drops out at once. With the map's owner away, no one can touch the map" },
        { id: 'room-03', pose: 'explain', text: "When someone enters the room, the system tells you at once and you will see their cursor moving on the map. Press the room badge on the top bar to see who is there, what they are editing and since when. Someone you kick cannot come back until you open a new room; someone you ban cannot enter this map's rooms again until you lift the ban" },
        { id: 'room-04', names: ["This map"], far: ["Restore the map to before the last room was opened"], pose: 'mad', spot: '#setcard', text: "As for a friend who gets too playful and paints sea over your continent for fun, I won't make you put up with it. Each time before a room opens, the system keeps one copy of the map. Once you have opened a room, a button appears in the this-map card to restore the map to before the last room opened. One press and all your work comes back" },
        { id: 'room-05', pose: 'guilty', text: "This practice map cannot open a room; save that for your real maps. And I must tell you plainly that online rooms are still being tested. If you cannot connect, try opening this page from its link directly once more" }
      ] },
      { id: 'keep', nav: "Keeping your maps safe", title: "Precious things need copies", mode: 'view', steps: [
        { id: 'keep-01', pose: 'panic', text: "The last matter is the most important. Every map is kept only in this device's browser. There is no copy anywhere else. Clear the browser's data and the maps go with it",
          poseBk: 'shush', textBk: "The last matter is the most important. Every map is kept in this device's browser, and this page keeps another private backup of yours that only your account can read. If you clear the browser's data or move to another device, the maps come back by themselves when you open this page with the same account. The cards in the library always show which maps are backed up on this page" },
        { id: 'keep-02', names: ["This map", "Save this practice map to the library"], far: ["Import a map file", "Back up the whole library as one file"], pose: 'explain', spot: '#setcard, #setExport', text: "Guard them one layer further by exporting map files. On your real maps, the export button is in the this-map card, where this practice map has keep-this-practice-map-in-the-library instead. You get one file per map, to move devices or send to a friend. The menu page has an import-map-file button and a button to back up the whole library as one file" },
        { id: 'keep-03', pose: 'think', text: "A map's card in the library always shows when it was last backed up and whether it has been edited since. Whenever you see the warning, export again. It takes only a moment" },
        { id: 'keep-04', names: ["Save map image"], far: ["Edits on the map"], pose: 'explain', spot: '#expPng', text: "For a picture to use in a book or on the game table, the save-map-image button is in the on-map edits card. The image carries the names and routes you have turned on" },
        { id: 'keep-04b', names: ["Cut a part into a new map"], pose: 'explain', spot: '#setCrop', text: "To tell the story of a single realm of the continent, press cut a part into a new map in the this-map card, then drag a frame around the part you want. The land, rivers, communities, roads, states, notes and climate inside the frame go out as a new map in the library. The original does not move a single hex" },
        { id: 'keep-05', pose: 'smile', text: "Now you know every pen on the table, my child. The rest is your own world. Go and build it. Wherever you get stuck, you can always come back to me. I am on the menu page" }
      ] }
    ],
    // what she says when the thing she asked for is done
    praise: { view: "See? The map moves with your hand now", undo: "Good. The land changes at the tip of your brush now", rivers: "The water finds its own way to the sea now, see?", cities: "Your first city stands. May its people live well and eat well", clim: "Good. Switch layers and see what follows", eco: "Good. Wait a moment: trade across the whole map is being worked out again from what you changed", states: "There are states on the land now. From here on, trade must heed the voice of the borders" },
    taskLabel: { view: "Try it: move or zoom the map", undo: "Try it: paint a patch of terrain", rivers: "Try it: press place rivers automatically, or draw one river yourself", cities: "Try it: place one city", clim: "Try it: change the elevation, moisture or temperature of a hex", eco: "Try it: adjust one good", states: "Try it: give the map states and borders" }
  };
})();
